import{_ as t,o as e,c as r,a2 as l}from"./chunks/framework.Cd7uensT.js";const i="/idc_assest-docs/images/screenshots/backup-management.png",p=JSON.parse('{"title":"备份管理","description":"","frontmatter":{},"headers":[],"relativePath":"guide/features/backup-management.md","filePath":"guide/features/backup-management.md","lastUpdated":1785486863000}'),o={name:"guide/features/backup-management.md"};function d(n,a,s,h,c,u){return e(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="备份管理" tabindex="-1">备份管理 <a class="header-anchor" href="#备份管理" aria-label="Permalink to &quot;备份管理&quot;">​</a></h1><p>备份管理用于数据库的备份与恢复，保障数据安全。</p><p><img src="'+i+'" alt="备份管理概览"></p><h2 id="备份管理-1" tabindex="-1">备份管理 <a class="header-anchor" href="#备份管理-1" aria-label="Permalink to &quot;备份管理&quot;">​</a></h2><h3 id="手动备份" tabindex="-1">手动备份 <a class="header-anchor" href="#手动备份" aria-label="Permalink to &quot;手动备份&quot;">​</a></h3><ol><li>进入「备份管理」→「备份管理」页面</li><li>点击「创建备份」按钮</li><li>填写备份名称和描述（选填）</li><li>系统自动创建数据库备份文件</li><li>备份完成后显示在备份列表中，包含备份时间、文件大小、类型等信息</li></ol><h3 id="备份恢复" tabindex="-1">备份恢复 <a class="header-anchor" href="#备份恢复" aria-label="Permalink to &quot;备份恢复&quot;">​</a></h3><ol><li>在备份列表中选择要恢复的备份文件</li><li>点击「恢复」按钮</li><li>仔细阅读恢复提示（恢复会覆盖当前数据）</li><li>系统显示恢复进度，完成后自动重启服务</li></ol><blockquote><p>恢复前建议先对当前数据进行手动备份。</p></blockquote><h3 id="备份文件管理" tabindex="-1">备份文件管理 <a class="header-anchor" href="#备份文件管理" aria-label="Permalink to &quot;备份文件管理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><strong>上传</strong></td><td>上传外部备份文件到服务器，支持跨环境恢复</td></tr><tr><td><strong>下载</strong></td><td>下载备份文件到本地保存</td></tr><tr><td><strong>删除</strong></td><td>删除不需要的备份文件</td></tr><tr><td><strong>验证</strong></td><td>校验备份文件的完整性和可用性（显示表数量和记录数）</td></tr><tr><td><strong>清理</strong></td><td>批量清理旧备份，支持按保留份数和天数设置</td></tr></tbody></table><h2 id="自动备份" tabindex="-1">自动备份 <a class="header-anchor" href="#自动备份" aria-label="Permalink to &quot;自动备份&quot;">​</a></h2><p>配置 Cron 表达式设置备份执行时间，支持保留备份文件数量设置。启用自动备份后，系统按设定时间自动创建备份。</p><h2 id="远端备份" tabindex="-1">远端备份 <a class="header-anchor" href="#远端备份" aria-label="Permalink to &quot;远端备份&quot;">​</a></h2><p>支持将备份文件自动传输到远端存储，协议包括 FTP、SFTP、WebDAV、SMB。</p><h3 id="远端配置" tabindex="-1">远端配置 <a class="header-anchor" href="#远端配置" aria-label="Permalink to &quot;远端配置&quot;">​</a></h3><ol><li>进入「远端备份」标签</li><li>点击「添加配置」，填写远端存储信息</li><li>点击「测试连接」验证配置</li><li>测试通过后保存配置</li></ol><h3 id="手动同步" tabindex="-1">手动同步 <a class="header-anchor" href="#手动同步" aria-label="Permalink to &quot;手动同步&quot;">​</a></h3><p>选择本地备份文件，手动触发上传到远端存储。</p>',19)])])}const m=t(o,[["render",d]]);export{p as __pageData,m as default};
